// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract Attacker {
    ReentrancyDAO c;
    uint256 public got;
    bool attacking;

    constructor(ReentrancyDAO _c) {
        c = _c;
    }

    function deposit() external payable {
        c.deposit{value: msg.value}();
    }

    function attack() external {
        attacking = true;
        c.withdrawAll();
    }

    receive() external payable {
        got += msg.value;
        if (attacking && got < 2 && address(c).balance >= 1) {
            c.withdrawAll();
        }
    }
}

contract InvMutTest is Test {
    ReentrancyDAO c;
    Attacker att;

    function setUp() public {
        c = new ReentrancyDAO();
        att = new Attacker(c);
    }

    function testFuzz_run() public {
        vm.deal(address(this), 100);
        c.deposit{value: 5}();

        vm.deal(address(att), 10);
        att.deposit{value: 1}();

        att.attack();

        assertTrue(att.got() <= 1);
    }

    receive() external payable {}
}
